# setup_moodify.py
import os
import base64

files = {
    "moodify/database.py": "",
    "moodify/music.py": "",
    "moodify/analyzer.py": "",
    "moodify/app.py": "",
    "moodify/templates/index.html": "",
}

def setup():
    print("🚀 [Moodify Auto Setup] 프로젝트 환경 구성을 시작합니다...")
    dirs = [
        "moodify",
        "moodify/templates",
        "moodify/static",
        "moodify/static/css",
        "moodify/static/js"
    ]
    for d in dirs:
        os.makedirs(d, exist_ok=True)
        print(f"  📁 디렉토리 생성: {d}")

    for file_path, b64_content in files.items():
        content = base64.b64decode(b64_content.encode('ascii')).decode('utf-8')
        with open(file_path, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"  📄 파일 생성 완료: {file_path}")

    print("\n✅ 모든 파일 및 디렉토리 생성이 완료되었습니다!")
    print("▶ 실행 방법:")
    print("   cd moodify")
    print("   pip install flask requests openai")
    print("   python app.py")

if __name__ == "__main__":
    setup()
